/**
 * One board's full server-side config, pushed with every BoardState.
 */
public struct UiBoardConfig {
    public var sports: [UiSportConfig]
    public var brightness: UInt8
    public var power: Bool
    public var extraGameIds: [String]
    /**
     * Preference-driven games one-off removed from the rotation.
     */
    public var excludedGameIds: [String]
    public var focusedGameId: String?
    public var name: String?
    /**
     * Id of the server-declared off mode (`UiOffMode::id`). A STRING, never an
     * enum: a closed enum here would throw `unexpectedEnumCase` in the
     * generated Swift and abort the whole config decode the first time a
     * forked server named a mode this build had never heard of.
     */
    public var offMode: String
    /**
     * What the board is DOING: "scores", "off", or the id of the screen
     * INSTANCE held persistently ("clock", "weather.2"). A string for the
     * same closed-enum reason as `off_mode`. Label it with
     * `screen_label_for`, never by matching a descriptor id.
     */
    public var mode: String
    /**
     * The board's screen list in the user's order, verbatim from the
     * server — a current server always sends the resolved list. EMPTY means
     * the server predates screen lists; `resolved_screen_configs` then
     * synthesizes one from `off_mode`/`off_mode_params`.
     */
    public var screens: [UiScreenConfig]
    /**
     * Whether this board's server understands screen lists (`screens` is
     * non-empty). Gates add/remove/reorder/the idle timer, and selects
     * single- vs multi-select idle — see `screens_editable`,
     * `idle_single_select`.
     */
    public var screensSupported: Bool
    /**
     * Seconds each checked screen holds the panel while the board idles
     * through two or more, snapped to a preset (`idle_cycle_options`).
     */
    public var idleCycleSecs: UInt32
    /**
     * Unix ms at which the board's current idle rotation put its FIRST
     * screen up (protocol `BoardState.idle_since_ms`, never stored in the
     * config): None when it is not idling through two or more screens, or
     * the server predates it. Pass to `ring` with the current time.
     */
    public var idleSinceMs: UInt64?
    /**
     * The board-wide off-mode values (location, 24-hour), plus a MIRROR of
     * the per-screen values of each kind's first instance for older apps.
     * Per-screen values are read from `screens`, not from here.
     */
    public var offModeParams: [String: String]
    /**
     * Seconds each game holds the panel before the rotation advances.
     */
    public var dwellSecs: UInt32
    /**
     * Unix seconds when a button-sleep auto-wakes (None when not sleeping).
     */
    public var wakeAt: UInt64?
    /**
     * Spoiler display: true = strict (matchup + time only), false = normal.
     */
    public var strictSpoilers: Bool
    /**
     * Spoiler-protect every game on this board.
     */
    public var spoilerAll: Bool
    /**
     * One-off spoiler-hidden games (cleared by Reset, pruned as games end).
     */
    public var spoilerGameIds: [String]
    /**
     * One-off revealed games (exceptions that beat every protection rule).
     */
    public var revealedGameIds: [String]
    /**
     * Board-local IANA timezone name ("America/New_York"); nil = server-local.
     */
    public var timezone: String?
    /**
     * Firmware release channel this board follows (`set_fw_channel`).
     */
    public var fwChannel: UiFwChannel
    /**
     * Serve this board a synthetic slate instead of live games. Only the
     * GAMES change — every other setting on the board is untouched.
     */
    public var demoData: Bool
    /**
     * The nightly quiet window in minutes since the board's local midnight,
     * or nil when there is none. Two flat fields rather than a record, so the
     * "unset" case is one nil check in Swift.
     */
    public var quietStartMin: UInt16?
    public var quietEndMin: UInt16?
    /**
     * Let live games light the panel during the window.
     */
    public var quietAllowEvents: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(sports: [UiSportConfig], brightness: UInt8, power: Bool, extraGameIds: [String],
                /**
                    * Preference-driven games one-off removed from the rotation.
                    */ excludedGameIds: [String], focusedGameId: String?, name: String?,
                /**
                    * Id of the server-declared off mode (`UiOffMode::id`). A STRING, never an
                    * enum: a closed enum here would throw `unexpectedEnumCase` in the
                    * generated Swift and abort the whole config decode the first time a
                    * forked server named a mode this build had never heard of.
                    */ offMode: String,
                /**
                    * What the board is DOING: "scores", "off", or the id of the screen
